import os,re
pat=re.compile(r'^import\s+(\S+)',re.M)
def imports(m):
    p=m.replace('.','/')+'.lean'
    return pat.findall(open(p,errors='replace').read()) if os.path.exists(p) else []
def mod(p): return p[:-5].replace('/','.')
allm={mod(os.path.join(dp,f)) for dp,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
seen=set(); stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(m):
        if i.startswith('AlgebraicJacobian') and i not in seen: stack.append(i)
un=sorted(allm-seen)
print('UNROOTED:',len(un))
for u in un: print('  ',u)
